import json, sys
rows = [json.loads(l) for l in open('/Users/lekt9/.contracts/contracts.jsonl') if l.strip()]
satisfied = {r['id']: r for r in rows if r['event']=='satisfied'}
iterated = {}
for r in rows:
    if r['event']=='iterated':
        iterated.setdefault(r['id'],[]).append(r)
declared = {r['id']: r for r in rows if r['event']=='declared'}
# Auto-satisfied = satisfied with no prior iterated row
auto = [cid for cid in satisfied if cid not in iterated and declared.get(cid,{}).get('action') not in ('funnel','children-satisfy','agent-judges','funnel-first')]
print(f'Auto-satisfied (no iterate wave): {auto}')
sys.exit(len(auto))
"
